 decision('local:catalog:screening-in-economics',['local:catalog:economic-signaling'],'admit_distinct_information_mechanism','The less-informed party initiates screening; the informed party initiates signaling. These are different information-acquisition mechanisms.',['selection.proposed.json proposals 110–111; baseline-index candidate record']),
 decision('local:catalog:bond-finance',['Q44424','Q10863671','Q3196867'],'admit_distinct_financial_sense','A bond is a debt security with specified issuer repayment terms, not an interatomic attraction or a chemical phi bond. General debt is a wider class. The real chemistry homonym Q44424 should be named alongside the author’s phi-bond comparison.',['selection.proposed.json proposal 118; baseline-index concepts/Q44424, Q10863671 and Q3196867']),
